private func s(_ seconds: Double) -> MediaTime { MediaTime(seconds: seconds) }

/// Fixtures generated by CI before the build (see .github/workflows/ios.yml).
private func fixture(_ name: String) -> URL? {
    Bundle(for: BundleToken.self).url(forResource: name, withExtension: nil)
}
private final class BundleToken {}

@Suite("Silence detection")
struct SilenceTests {
    @Test func findsPausesBetweenTones() {
        let sr = 16_000.0
        // 1 s tone, 1.5 s silence, 1 s tone, 0.3 s silence (too short), 1 s tone.
        var samples: [Float] = []
        func tone(_ d: Double) { samples += (0..<Int(d * sr)).map { Float(sin(2 * .pi * 220 * Double($0) / sr) * 0.5) } }
        func gap(_ d: Double) { samples += (0..<Int(d * sr)).map { _ in Float.random(in: -0.001...0.001) } }
        tone(1); gap(1.5); tone(1); gap(0.3); tone(1)
        let ranges = SilenceDetector.silentRanges(samples, sampleRate: sr)
        #expect(ranges.count == 1)
        let r = try! #require(ranges.first)
        #expect(abs(r.lowerBound - 1.12) < 0.05)
        #expect(abs(r.upperBound - 2.38) < 0.05)
    }

    @Test func ignoresConstantAudio() {
        let samples = (0..<32_000).map { Float(sin(Double($0) * 0.1) * 0.4) }
        #expect(SilenceDetector.silentRanges(samples, sampleRate: 16_000).isEmpty)
    }

    @Test func endToEndRemovesSilenceFromEdit() async throws {
        var fx = try Fixture()
        defer { fx.cleanup() }
        try await fx.addVideo("talk", duration: 5, draw: SampleMedia.animated(hue: 0.3),
                              audioPattern: [(true, 1.5), (false, 1.5), (true, 2)])
        let ranges = try await SilenceDetector.detect(project: fx.project, resolver: fx.resolver)
        #expect(ranges.count == 1)
        fx.project.rippleDelete(ranges: ranges)
        let d = fx.project.layout.duration.seconds
        #expect(d > 3.6 && d < 3.9, "about 1.26 s of the 1.5 s pause should be cut, got \(d)")
    }
}

@Suite("Beat detection")
struct BeatTests {
    @Test(arguments: [0, 1, 2])
    func detectsSynthesizedTempo(index: Int) async throws {
        let track = SampleMedia.library[index]
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("beats-\(track.id)-\(UUID().uuidString).m4a")
        defer { try? FileManager.default.removeItem(at: url) }
        try SampleMedia.renderMusic(track, duration: 12, to: url)
        let result = try #require(try await BeatDetector.detect(url: url))
        print("BEAT \(track.name): detected \(result.bpm)")
        // Allow octave errors only if the grid still lands on true beats.
        let ratio = result.bpm / track.bpm
        #expect(abs(ratio - 1) < 0.03 || abs(ratio - 2) < 0.05 || abs(ratio - 0.5) < 0.03,
                "\(track.name): detected \(result.bpm) BPM, expected \(track.bpm)")
        let period = 60 / track.bpm
        let errors = result.beats.dropFirst().dropLast().map { b -> Double in
            let k = (b / period).rounded()
            return abs(b - k * period)
        }
        let meanError = errors.reduce(0, +) / Double(max(errors.count, 1))
        #expect(meanError < 0.035, "\(track.name): mean beat error \(meanError)s")
        print("BEAT \(track.name): \(String(format: "%.1f", result.bpm)) BPM, mean error \(String(format: "%.3f", meanError))s")
    }
}

@Suite("Auto enhance")
struct EnhanceTests {
    func image(gray: Double) -> CGImage {
        let ctx = CGContext(data: nil, width: 32, height: 32, bitsPerComponent: 8, bytesPerRow: 0,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        ctx.setFillColor(CGColor(srgbRed: gray, green: gray, blue: gray * 0.8, alpha: 1))
        ctx.fill(CGRect(x: 0, y: 0, width: 32, height: 32))
        return ctx.makeImage()!
    }

    @Test func brightensDarkAndDarkensBright() {
        let dark = AutoEnhancer.adjustments(for: AutoEnhancer.stats(of: image(gray: 0.15)))
        let bright = AutoEnhancer.adjustments(for: AutoEnhancer.stats(of: image(gray: 0.85)))
        #expect(dark.exposure > 0.3)
        #expect(bright.exposure < -0.3)
        // Warm (yellowish) cast is cooled.
        #expect(dark.warmth <= 0)
        // Flat images get more contrast.
        #expect(dark.contrast > 0)
    }
}

@Suite("Auto reframe")
struct ReframeTests {
    @Test func smoothingHasDeadZone() {
        let samples = (0..<10).map { Reframer.Sample(time: s(Double($0) * 0.25), target: SIMD2(0.52, 0.5)) }
        let keys = Reframer.smooth(samples)
        #expect(keys.allSatisfy { $0.centerX == 0.52 })
        let moving = (0..<20).map { Reframer.Sample(time: s(Double($0) * 0.25), target: SIMD2(0.2 + Double($0) * 0.03, 0.5)) }
        let path = Reframer.smooth(moving)
        #expect(path.last!.centerX > path.first!.centerX + 0.3)
    }

    /// A face sliding left → right across a wide frame (face detection runs in the simulator).
    @Test func followsMovingFace() async throws {
        guard let url = fixture("portrait.jpg"),
              let src = CGImageSourceCreateWithURL(url as CFURL, nil),
              let face = CGImageSourceCreateImageAtIndex(src, 0, nil) else {
            withKnownIssue("portrait.jpg fixture missing") { throw CaptionError.noSpeechFound }
            return
        }
        let video = FileManager.default.temporaryDirectory.appendingPathComponent("face-\(UUID().uuidString).mov")
        defer { try? FileManager.default.removeItem(at: video) }
        try await SampleMedia.makeVideo(url: video, size: CGSize(width: 960, height: 400), duration: 3) { ctx, size, t in
            ctx.setFillColor(CGColor(gray: 0.15, alpha: 1))
            ctx.fill(CGRect(origin: .zero, size: size))
            let h = size.height * 0.9, w = h * CGFloat(face.width) / CGFloat(face.height)
            let x = (size.width - w) * (0.05 + 0.9 * t / 3)
            // Context is flipped to top-left origin; draw the image upright.
            ctx.saveGState()
            ctx.translateBy(x: x, y: (size.height - h) / 2 + h)
            ctx.scaleBy(x: 1, y: -1)
            ctx.draw(face, in: CGRect(x: 0, y: 0, width: w, height: h))
            ctx.restoreGState()
        }
        let keys = try await Reframer.analyze(url: video, range: MediaTimeRange(start: .zero, duration: s(3)))
        let first = keys.first!.centerX, last = keys.last!.centerX
        print("REFRAME error: \(VisionSupport.lastError ?? "-") path: \(keys.map { String(format: "%.2f", $0.centerX) }.joined(separator: " "))")
        #expect(last > first + 0.3, "reframe should pan with the face: \(first) → \(last)")
    }

@Suite("Captions")
struct CaptionTests {
    @Test func groupsWordsIntoSegments() {
        var words: [CaptionWord] = []
        var t = 0.0
        for (i, w) in "Hello there. This is a quick test of the caption grouping logic".split(separator: " ").enumerated() {
            words.append(CaptionWord(text: String(w), range: MediaTimeRange(start: s(t), duration: s(0.3))))
            t += i == 6 ? 1.0 : 0.35
        }
        let segments = CaptionGenerator.segments(from: words)
        #expect(segments.first?.text == "Hello there.")
        #expect(segments.allSatisfy { $0.words.count <= 5 })
        #expect(segments.flatMap(\.words).count == words.count)
    }

    @Test func splitsMultiWordRuns() {
        let words = CaptionGenerator.splitRun(" big red dog", start: 1, end: 2)
        #expect(words.map(\.text) == ["big", "red", "dog"])
        #expect(abs(words[0].range.start.seconds - 1) < 0.001)
        #expect(abs(words[2].range.end.seconds - 2) < 0.01)
    }

    /// Real speech generated by macOS `say` on the CI runner.
    @Test func transcribesSpeechOnDevice() async throws {
        guard let url = fixture("speech.m4a") else {
            Issue.record("speech.m4a fixture missing – generated by CI")
            return
        }
        do {
            let (words, engine) = try await CaptionGenerator.transcribe(url: url)
            let text = words.map(\.text).joined(separator: " ").lowercased()
            print("CAPTIONS [\(engine.rawValue)]: \(text)")
            #expect(text.contains("caption") || text.contains("device") || text.contains("welcome"))
            // Timestamps increase and fall inside the file.
            #expect(zip(words, words.dropFirst()).allSatisfy { $0.range.start <= $1.range.start })
        } catch {
            print("CAPTIONS analyzer failure: \(CaptionGenerator.lastAnalyzerFailure ?? "-")")
            // The iOS simulator may not ship on-device speech models; report rather than fail silently.
            withKnownIssue("On-device speech recognition unavailable in this simulator: \(error)") {
                throw error
            }
        }
    }
}

@Suite("Background removal")
struct SegmentationTests {
    @Test func findsPersonInPortrait() throws {
        guard let url = fixture("portrait.jpg"),
              let src = CGImageSourceCreateWithURL(url as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(src, 0, nil) else {
            withKnownIssue("portrait.jpg fixture could not be downloaded on CI") { throw CaptionError.noSpeechFound }
            return
        }
        let coverage = SubjectSegmenter.personCoverage(in: image)
        #if targetEnvironment(simulator)
        if coverage == 0 {
            // The simulator ships without the person-segmentation model: Vision returns no
            // mask and no error. This must be verified on an iPhone.
            withKnownIssue("Person segmentation model unavailable in the iOS simulator") {
                #expect(coverage > 0.15)
            }
            return
        }
        #endif
        print("SEGMENTATION coverage: \(coverage) error: \(VisionSupport.lastError ?? "-")")
        #expect(coverage > 0.15 && coverage < 0.95)
    }

    /// Diagnostics: does Vision run at all in this environment?
    @Test func visionFaceProbe() throws {
        guard let url = fixture("portrait.jpg"),
              let src = CGImageSourceCreateWithURL(url as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return }
        let center = Reframer.subjectCenter(in: image)
        print("SEGMENTATION face probe: \(String(describing: center)) error: \(VisionSupport.lastError ?? "-")")
    }

    @Test func noPersonInAbstractImage() {
        let ctx = CGContext(data: nil, width: 256, height: 256, bitsPerComponent: 8, bytesPerRow: 0,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        ctx.setFillColor(CGColor(srgbRed: 0.2, green: 0.4, blue: 0.9, alpha: 1))
        ctx.fill(CGRect(x: 0, y: 0, width: 256, height: 256))
        #expect(SubjectSegmenter.personCoverage(in: ctx.makeImage()!) < 0.05)
    }

    @Test func compositorAppliesBackgroundReplacement() async throws {
        var fx = try Fixture()
        defer { fx.cleanup() }
        try await fx.addVideo("plain", duration: 1, draw: SampleMedia.solid(RGBAColor(r: 0.9, g: 0.9, b: 0.9)))
        // No person in frame → mask is empty → everything is replaced by the colour.
        // (In the simulator Vision returns no mask at all, so the clip renders unmasked.)
        try fx.project.updateClip(fx.project.clips[0].id) {
            $0.backgroundRemoval = .color(RGBAColor(r: 0, g: 1, b: 0))
            $0.transform.fit = .fill
        }
        let built = try await CompositionBuilder().build(project: fx.project, resolver: fx.resolver,
                                                         renderSize: CGSize(width: 180, height: 320))
        let c = averageColor(try await renderFrame(built, at: 0.5))
        #expect(c.y > 0.8 && c.x < 0.3, "background should be replaced with green, got \(c)")
    }
}
